using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change #1: EF 9 renamed "Discriminator" to "$type".
            // Preserve the old property name for existing documents.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking change #2: EF 9 changed id format from "EntityType|Key" to just "Key".
            // Preserve the old format for existing documents.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();

            // Breaking change #3: Cosmos DB does not support indexes defined via EF.
            // HasIndex() now throws at model validation in EF 9. Removed.
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // Breaking change #4: EF 9 uses sync-over-async by default for Cosmos which is
    // deprecated. SyncJob.Run() uses synchronous .ToList() / .SaveChanges().
    // Either switch to async or set EnableSyncExecution (see SyncJob.cs).
}

